import './StatusList.css';
import type { Status, StatusItem } from '../../types';

export const STATUS_LABELS: Record<Status, string> = {
  'todo': 'To Do',
  'in-progress': 'In Progress',
  'done': 'Done',
  'blocked': 'Blocked',
};

export const SKELETON_COUNT = 6;

export function statusColor(status: Status): string {
  switch (status) {
    case 'todo':
      return 'status-item-todo';
    case 'in-progress':
      return 'status-item-in-progress';
    case 'done':
      return 'status-item-done';
    case 'blocked':
      return 'status-item-blocked';
  }
}

interface StatusListProps {
  items: StatusItem[] | null;
}

const STATUS_ORDER: Status[] = ['in-progress', 'blocked', 'todo', 'done'];

export function StatusList({ items }: StatusListProps): JSX.Element {
  if (items === null) {
    return (
      <ul className="status-list" aria-busy="true" aria-label="Loading items">
        {Array.from({ length: SKELETON_COUNT }, (_, i) => (
          <li key={i} className="status-item-skeleton">
            <span className="skeleton-line" />
          </li>
        ))}
      </ul>
    );
  }

  const groups: Map<Status, StatusItem[]> = new Map();
  for (const status of STATUS_ORDER) {
    groups.set(status, []);
  }
  for (const item of items) {
    const group = groups.get(item.status);
    if (group !== undefined) {
      group.push(item);
    }
  }

  return (
    <div className="status-list">
      {STATUS_ORDER.map((status) => {
        const groupItems = groups.get(status);
        if (!groupItems || groupItems.length === 0) {
          return null;
        }
        return (
          <section key={status} className="status-group">
            <h2 className="status-group-heading">{STATUS_LABELS[status]}</h2>
            <ul className="status-group-items">
              {groupItems.map((item) => (
                <li key={item.id} className={`status-item ${statusColor(item.status)}`}>
                  {item.title}
                </li>
              ))}
            </ul>
          </section>
        );
      })}
    </div>
  );
}

