import { useEffect, useState } from 'react';
import { getTasks } from '../../api';
import type { StatusItem } from '../../types';
import './TaskBoard.css';

const SKELETON_COUNT = 5;

function TaskList({ tasks }: { tasks: StatusItem[] | null }): JSX.Element {
  if (tasks === null) {
    return (
      <ul className="task-board-list" aria-busy="true" aria-label="Loading tasks">
        {Array.from({ length: SKELETON_COUNT }, (_, i) => (
          <li key={i} className="task-board-skeleton-item">
            <span className="task-board-skeleton-line" />
          </li>
        ))}
      </ul>
    );
  }

  if (tasks.length === 0) {
    return <p className="task-board-empty">No tasks yet</p>;
  }

  return (
    <ul className="task-board-list">
      {tasks.map((task) => (
        <li key={task.id} className="task-board-item">
          {task.title}
        </li>
      ))}
    </ul>
  );
}

export function TaskBoard(): JSX.Element {
  // null = loading; array = loaded
  const [tasks, setTasks] = useState<StatusItem[] | null>(null);

  useEffect(() => {
    getTasks()
      .then((data) => setTasks(data))
      .catch(() => setTasks([]));
  }, []);

  return (
    <div className="task-board">
      <header className="task-board-header">
        <h1 className="task-board-title">Tasks</h1>
        {tasks !== null && (
          <span className="task-board-badge" aria-label={`${tasks.length} tasks`}>
            {tasks.length}
          </span>
        )}
      </header>
      <div className="task-board-filter-bar" />
      <TaskList tasks={tasks} />
    </div>
  );
}

