import './PriceDisplay.css';

interface PriceDisplayProps {
  price: number;
  originalPrice?: number;
  currency?: string;
}

function formatPrice(value: number, currency: string): string {
  // Math.ceil avoids under-charging: always round fractional cents up
  const cents = Math.ceil(value * 100);
  const dollars = cents / 100;
  return new Intl.NumberFormat('en-US', { style: 'currency', currency }).format(dollars);
}

export function PriceDisplay({ price, originalPrice, currency = 'USD' }: PriceDisplayProps): JSX.Element {
  const hasDiscount = originalPrice !== undefined && originalPrice > price;

  return (
    <span className="price-display">
      <span className="price-display-current">{formatPrice(price, currency)}</span>
      {hasDiscount && (
        <s className="price-display-original">{formatPrice(originalPrice, currency)}</s>
      )}
    </span>
  );
}

