import './ChipBar.css';
import type { Status } from '../../types';

interface ChipBarProps {
  statuses: Status[];
  selected: Set<Status>;
  onSelectionChange: (updated: Set<Status>) => void;
}

export function ChipBar({ statuses, selected, onSelectionChange }: ChipBarProps): JSX.Element {
  function handleClick(status: Status): void {
    const updated = new Set(selected);
    if (updated.has(status)) {
      updated.delete(status);
    } else {
      updated.add(status);
    }
    onSelectionChange(updated);
  }

  return (
    <div className="chip-bar" role="group">
      {statuses.map((status) => (
        <button
          key={status}
          className="chip"
          aria-pressed={selected.has(status)}
          onClick={() => handleClick(status)}
        >
          {status}
        </button>
      ))}
    </div>
  );
}

